<?php

declare(strict_types=1);

namespace Drupal\solo_utilities\Settings;

/**
 * Cross-field rules of the Solo settings form.
 *
 * GENERATED by solo_utilities/scripts/settings-gen/solo-schema-gen.py from
 * solo-2.0-compat.yml and solo-2.0-constraints.yml. Never edit by hand.
 *
 * @internal
 */
final class CompatibilityRules {

  /**
   * The rules, keyed by id.
   *
   * @var array<string, array<string, mixed>>
   */
  public const RULES = [
    'C3a' => [
      'kind' => 'states_invisible',
      'when' => [['path' => 'preloader.force_show', 'value' => 'checked']],
      'targets' => ['preloader.disable_authenticated', 'preloader.disable_admin_routes', 'preloader.path_rules'],
    ],
    'C3b' => [
      'kind' => 'warn_when',
      'when' => [
        ['path' => 'preloader.force_show', 'value' => 'checked'],
        ['path' => 'preloader.enabled', 'value' => 'unchecked'],
      ],
    ],
    'C5' => [
      'kind' => 'error_floor',
      'path' => 'popup_login.z_index',
      'min' => 5002,
    ],
    'C11' => [
      'kind' => 'warn_order',
      'smaller' => 'layout.breakpoints.menu',
      'larger' => 'layout.breakpoints.page',
    ],
    'C14' => [
      'kind' => 'states_invisible',
      'when' => [['path' => 'layout.width.global', 'value' => 'sw-100']],
      'targets' => ['layout.width.use_pixels'],
    ],
  ];

  /**
   * Returns one rule.
   *
   * @return array<string, mixed>
   *   The rule.
   */
  public static function rule(string $id): array {
    return self::RULES[$id];
  }

  /**
   * Returns the #states of one target field of a states rule.
   *
   * @return array<string, mixed>
   *   The #states array.
   */
  public static function states(string $id, string $target): array {
    $rule = self::RULES[$id];
    if ($rule['kind'] !== 'states_invisible' || !in_array($target, $rule['targets'], TRUE)) {
      return [];
    }
    $when = $rule['when'][0];
    $segments = explode('.', $when['path']);
    $name = array_shift($segments) . ($segments === [] ? '' : '[' . implode('][', $segments) . ']');
    /** @var string $when_value */
    $when_value = $when['value'];
    $condition = match ($when_value) {
      'checked' => ['checked' => TRUE],
      'unchecked' => ['checked' => FALSE],
      default => ['value' => $when_value],
    };
    return ['invisible' => [':input[name="' . $name . '"]' => $condition]];
  }

}
